per_call.cmd:
set -e
mkdir -p /var/www/html
printf 'Welcome to the benchmark webserver\n' > /var/www/html/index.html
printf 'Page not found - Please check your URL\n' > /var/www/html/404.html
rm -f /etc/nginx/sites-enabled/default
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10 nodelay;

    error_page 404 /404.html;
    location = /404.html {
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
python3 - <<'PYEOF'
p = '/etc/nginx/nginx.conf'
s = open(p).read()
anchor = 'access_log /var/log/nginx/access.log;'
insert = """
\t# Custom benchmark log format
\tlog_format benchmark '$time_local $request_method $status "$http_user_agent"';

\t# Rate limiting zone
\tlimit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;
"""
if 'log_format benchmark' not in s or 'limit_req_zone' not in s:
    s = s.replace(anchor, anchor + insert, 1)
open(p, 'w').write(s)
print('nginx.conf updated')
PYEOF
grep -n 'log_format benchmark\|limit_req_zone' /etc/nginx/nginx.conf
